// =====================================================================
// ETAPAS 2 e 3 | CONSOLIDAR E EXTRAIR
// Recebe a entrada de qualquer canal (WhatsApp, E-mail, Portal, TXT/CSV, PDF)
// e devolve UM registro por solicitação, sempre no mesmo formato:
//   { canal, origem, recebido_em, campos_brutos, teste, cenario, crm_simulado }
// Nada é descartado aqui: entradas vazias também seguem e serão reprovadas na validação.
// =====================================================================

// Em produção só um node de entrada executa por vez; descobrimos qual foi.
const NODES_DE_ENTRADA = {
  'Webhook WhatsApp': 'whatsapp',
  'Webhook E-mail': 'email',
  'Webhook Portal': 'portal',
  'Webhook Arquivo TXT/CSV': 'arquivo',
  'Extrair Texto do PDF': 'arquivo_pdf',
};
const executou = (nome) => { try { return $(nome).isExecuted; } catch (e) { return false; } };
const canalDaExecucao = () =>
  Object.keys(NODES_DE_ENTRADA).filter(executou).map((n) => NODES_DE_ENTRADA[n])[0] || 'desconhecido';

const texto = (v) => (v === null || v === undefined ? '' : String(v));

// Corpo do webhook como objeto (aceita JSON ou texto puro)
function corpo(json) {
  let b = json.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = { mensagem: b }; } }
  return b && typeof b === 'object' && !Array.isArray(b) ? b : {};
}

// "Nome <email@x.com>" -> { nome, email }
function lerRemetente(from) {
  const m = texto(from).match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
  return m ? { nome: m[1].trim(), email: m[2].trim() } : { nome: '', email: texto(from).trim() };
}

// TXT/PDF: linhas "Chave: valor" viram campos; linhas sem chave viram a mensagem
function lerChaveValor(conteudo) {
  const campos = {}; const livres = [];
  for (const linha of texto(conteudo).split(/\r?\n/)) {
    const m = linha.match(/^\s*([A-Za-zÀ-ÿ _-]{1,40}):\s*(.*)$/);
    if (m) campos[m[1].trim()] = m[2].trim();
    else if (linha.trim()) livres.push(linha.trim());
  }
  if (livres.length) campos.mensagem = [campos.mensagem, ...livres].filter(Boolean).join(' ');
  return campos;
}

// CSV: separador ; ou , (detectado no cabeçalho), aspas respeitadas
function lerCsv(conteudo) {
  const linhas = texto(conteudo).split(/\r?\n/).filter((l) => l.trim());
  if (linhas.length < 2) return [];
  const sep = (linhas[0].match(/;/g) || []).length >= (linhas[0].match(/,/g) || []).length ? ';' : ',';
  const dividir = (linha) => {
    const cols = []; let atual = ''; let aspas = false;
    for (const ch of linha) {
      if (ch === '"') aspas = !aspas;
      else if (ch === sep && !aspas) { cols.push(atual); atual = ''; }
      else atual += ch;
    }
    cols.push(atual);
    return cols.map((c) => c.trim());
  };
  const cab = dividir(linhas[0]);
  return linhas.slice(1).map((l, i) => {
    const v = dividir(l); const campos = {};
    cab.forEach((c, k) => { campos[c] = v[k] ?? ''; });
    return { linha: i + 2, campos };
  });
}

const agora = new Date().toISOString();
const saida = [];

for (const item of $input.all()) {
  const j = item.json;
  const b = corpo(j);
  let canal = j._canal || canalDaExecucao();
  let registros = [];   // [{ campos, origem }]

  if (canal === 'whatsapp') {
    const { from, ...resto } = b;                       // "from" é o número do remetente
    registros = [{ campos: from ? { ...resto, celular: from } : resto, origem: {} }];
  } else if (canal === 'email') {
    const { from, subject, text, ...resto } = b;
    const r = lerRemetente(from);
    registros = [{ campos: { ...resto, nome: r.nome, email: r.email, assunto: subject, mensagem: text }, origem: {} }];
  } else if (canal === 'portal') {
    registros = [{ campos: { ...b }, origem: {} }];
  } else if (canal === 'arquivo') {
    const arquivo = texto(b.nome_arquivo);
    const ext = texto(b.tipo_arquivo || arquivo.split('.').pop()).toLowerCase();
    if (ext === 'csv') {
      canal = 'arquivo_csv';
      const linhas = lerCsv(b.conteudo);
      registros = linhas.length
        ? linhas.map((l) => ({ campos: l.campos, origem: { arquivo, linha: l.linha } }))
        : [{ campos: {}, origem: { arquivo, aviso: 'CSV sem linhas de dados' } }];
    } else {
      canal = 'arquivo_txt';
      registros = [{ campos: lerChaveValor(b.conteudo), origem: { arquivo } }];
    }
  } else if (canal === 'arquivo_pdf') {
    let arquivo = texto(j.nome_arquivo);
    try { arquivo = arquivo || $('Webhook Arquivo PDF').first().binary.data.fileName; } catch (e) { /* sem nome */ }
    registros = [{ campos: lerChaveValor(j.text), origem: { arquivo: texto(arquivo) } }];   // "text" vem do node Extract From File
  } else {
    registros = [{ campos: b, origem: { aviso: 'canal não identificado' } }];
  }

  for (const r of registros) {
    saida.push({ json: {
      canal, origem: r.origem, recebido_em: agora, campos_brutos: r.campos,
      teste: !!j._teste, cenario: j._cenario || null, crm_simulado: j._crm_simulado || null,
    } });
  }
}
return saida;

// =====================================================================
// ETAPA 4 | MAPEAR CAMPOS
// Reconhece nomes equivalentes (celular = fone = telefone ...) e padroniza a ESTRUTURA
// dos campos. Os valores ainda NÃO são alterados aqui.
// Saída: dados (campos padronizados) + mapeamentos + campos_nao_mapeados + conflitos
// =====================================================================

const SINONIMOS = {
  nome: ['nome', 'nome_cliente', 'cliente', 'nome_completo', 'razao_social', 'solicitante', 'name'],
  telefone: ['telefone', 'celular', 'fone', 'tel', 'whatsapp', 'phone'],
  email: ['email', 'e_mail', 'mail'],
  documento: ['documento', 'cpf', 'cnpj', 'cpf_cnpj', 'doc'],
  data_pedido: ['data_pedido', 'data', 'data_solicitacao', 'data_do_pedido', 'dt_pedido'],
  tipo: ['tipo', 'assunto', 'motivo', 'tipo_solicitacao', 'subject'],
  observacao: ['observacao', 'obs', 'mensagem', 'descricao', 'texto', 'detalhes', 'message'],
  nota_fiscal: ['nota_fiscal', 'nf', 'num_nf', 'nfe'],
};

// "Nome Cliente" -> "nome_cliente" ; "Observação" -> "observacao"
const chave = (k) => String(k).normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().trim().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');

const PARA_CANONICO = {};
for (const [canonico, apelidos] of Object.entries(SINONIMOS)) apelidos.forEach((a) => { PARA_CANONICO[a] = canonico; });

// Dois valores "dizem a mesma coisa"? (telefone/documento/NF comparam só dígitos)
function mesmoValor(campo, a, b) {
  if (['telefone', 'documento', 'nota_fiscal'].includes(campo)) return a.replace(/\D/g, '') === b.replace(/\D/g, '');
  return chave(a) === chave(b);
}

return $input.all().map((item) => {
  const dados = {}; const mapeamentos = []; const naoMapeados = {}; const conflitos = [];

  for (const [campoOriginal, bruto] of Object.entries(item.json.campos_brutos || {})) {
    const destino = PARA_CANONICO[chave(campoOriginal)];
    if (!destino || (bruto !== null && typeof bruto === 'object')) { naoMapeados[campoOriginal] = bruto; continue; }
    mapeamentos.push({ origem: campoOriginal, destino, renomeado: campoOriginal !== destino });

    const valor = String(bruto ?? '').trim();
    if (valor === '') continue;                                    // vazio = ausente (não inventamos nada)
    if (dados[destino] === undefined) dados[destino] = valor;
    else if (!mesmoValor(destino, dados[destino], valor)) {
      conflitos.push({ campo: destino, valores: [dados[destino], valor] });   // dois campos equivalentes com valores diferentes
    }
  }
  return { json: { ...item.json, dados, mapeamentos, campos_nao_mapeados: naoMapeados, conflitos } };
});

// =====================================================================
// ETAPAS 5 e 6 | AUDITAR E VALIDAR
// 1) Audita o lote: total, válidos, inválidos, duplicados, ausências por campo, por canal.
// 2) Valida cada registro com critérios explícitos e define status_validacao:
//      "Válido" | "Inválido" (campo ausente / valor inconsistente / conflito) | "Duplicado"
// Cada reprovação carrega a lista "motivos" (nada é descartado em silêncio).
// =====================================================================

const CAMPOS = ['nome', 'telefone', 'email', 'documento', 'data_pedido', 'tipo', 'observacao', 'nota_fiscal'];

const digitos = (s) => String(s ?? '').replace(/\D/g, '');
const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();

// Telefone brasileiro -> DDD+número (10 ou 11 dígitos) ou null. Remove +55 quando presente.
function parseTelefone(valor) {
  let d = digitos(valor);
  if ((d.length === 12 || d.length === 13) && d.startsWith('55')) d = d.slice(2);
  if (d.length === 10 && /^[1-9]{2}[2-9]/.test(d)) return d;   // fixo
  if (d.length === 11 && /^[1-9]{2}9/.test(d)) return d;       // celular
  return null;
}

// Data -> AAAA-MM-DD ou null. Aceita AAAA-MM-DD e DD/MM/AAAA (também com - ou .).
// Ano com 2 dígitos é ambíguo: não adivinhamos.
function parseData(valor) {
  const s = String(valor ?? '').trim();
  let a; let mes; let dia; let m;
  if ((m = s.match(/^(\d{4})-(\d{2})-(\d{2})(?:[T ].*)?$/))) { a = +m[1]; mes = +m[2]; dia = +m[3]; }
  else if ((m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/))) { dia = +m[1]; mes = +m[2]; a = +m[3]; }
  else return null;
  const dt = new Date(Date.UTC(a, mes - 1, dia));
  if (dt.getUTCFullYear() !== a || dt.getUTCMonth() !== mes - 1 || dt.getUTCDate() !== dia) return null;  // ex.: 31/02
  return `${a}-${String(mes).padStart(2, '0')}-${String(dia).padStart(2, '0')}`;
}

const emailValido = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);

// Hash FNV-1a (64 bits = 2 sementes) para gerar o identificador determinístico do registro
function fnv(txt, seed) {
  let h = seed;
  for (const ch of txt) { h ^= ch.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}
const hash = (txt) => fnv(txt, 0x811c9dc5) + fnv(txt, 0x9747b28c);

const itens = $input.all();
const vistos = new Map();   // chave_registro -> quantas vezes já apareceu neste lote

// ---- Validação registro a registro ----
const resultados = itens.map((item, i) => {
  const j = item.json; const d = j.dados || {};
  const motivos = [];
  const add = (codigo, campo, descricao) => motivos.push({ codigo, campo, descricao });

  // Obrigatórios
  if (!d.nome) add('AUSENTE', 'nome', 'Nome do cliente não informado');
  if (!d.telefone && !d.email) add('AUSENTE', 'telefone/email', 'Nenhum contato informado (telefone ou e-mail)');
  if (!d.tipo && !d.observacao) add('AUSENTE', 'tipo/observacao', 'Sem tipo nem observação para identificar a solicitação');
  // Valores inconsistentes (só avalia o que foi informado)
  if (d.telefone && !parseTelefone(d.telefone)) add('INCONSISTENTE', 'telefone', `Telefone fora do padrão brasileiro: "${d.telefone}"`);
  if (d.email && !emailValido(d.email)) add('INCONSISTENTE', 'email', `E-mail inválido: "${d.email}"`);
  if (d.data_pedido && !parseData(d.data_pedido)) add('INCONSISTENTE', 'data_pedido', `Data inválida ou ambígua: "${d.data_pedido}"`);
  if (d.documento && ![11, 14].includes(digitos(d.documento).length)) add('INCONSISTENTE', 'documento', `CPF/CNPJ com quantidade de dígitos inválida: "${d.documento}"`);
  for (const c of j.conflitos || []) add('CONFLITO', c.campo, `Campos equivalentes com valores diferentes: ${c.valores.map((v) => `"${v}"`).join(' x ')}`);

  // Duplicidade: mesmo conteúdo (após padronizar) já visto neste lote
  const base = [semAcento(d.nome), parseTelefone(d.telefone) || digitos(d.telefone) || semAcento(d.email),
    parseData(d.data_pedido) || '', semAcento(`${d.tipo || ''} ${d.observacao || ''}`)].join('|');
  const chave = 'rdx-' + (base.replace(/\|/g, '') === ''
    ? hash(`${j.canal}|${JSON.stringify(j.origem)}|${i}`)     // registro sem conteúdo: chave própria (não vira "duplicado")
    : hash(base));
  const ocorrencia = (vistos.get(chave) || 0) + 1;
  vistos.set(chave, ocorrencia);
  if (ocorrencia > 1) add('DUPLICADO', 'registro', `Mesmo conteúdo já recebido neste lote (ocorrência ${ocorrencia})`);

  const reprovadoPorDado = motivos.some((m) => m.codigo !== 'DUPLICADO');
  const status = reprovadoPorDado ? 'Inválido' : ocorrencia > 1 ? 'Duplicado' : 'Válido';
  const preenchidos = CAMPOS.filter((c) => d[c]).length;

  return { j, motivos, status, chave, ocorrencia, preenchidos };
});

// ---- Auditoria estatística do lote ----
const lote = { total: resultados.length, validos: 0, invalidos: 0, duplicados: 0, por_canal: {}, ausencias_por_campo: {}, completude_media_pct: 0 };
let somaCompletude = 0;
for (const r of resultados) {
  if (r.status === 'Válido') lote.validos++; else if (r.status === 'Duplicado') lote.duplicados++; else lote.invalidos++;
  lote.por_canal[r.j.canal] = (lote.por_canal[r.j.canal] || 0) + 1;
  CAMPOS.filter((c) => !(r.j.dados || {})[c]).forEach((c) => { lote.ausencias_por_campo[c] = (lote.ausencias_por_campo[c] || 0) + 1; });
  somaCompletude += (r.preenchidos / CAMPOS.length) * 100;
}
lote.completude_media_pct = lote.total ? Math.round(somaCompletude / lote.total) : 0;

return resultados.map((r) => ({ json: {
  ...r.j,
  chave_registro: r.chave,
  chave_pendencia: r.ocorrencia > 1 ? `${r.chave}-dup${r.ocorrencia}` : r.chave,   // duplicado não sobrescreve o original
  status_validacao: r.status,
  motivos: r.motivos,
  motivos_resumo: r.motivos.map((m) => `${m.campo}: ${m.descricao}`).join('; '),
  dados_originais_json: JSON.stringify(r.j.campos_brutos || {}),
  auditoria: { registro: { campos_preenchidos: r.preenchidos, campos_total: CAMPOS.length, completude_pct: Math.round((r.preenchidos / CAMPOS.length) * 100) }, lote },
} }));

// =====================================================================
// ETAPAS 7 e 8 | NORMALIZAR DADOS  (só registros aprovados chegam aqui)
// 1) Remove campos desnecessários: tudo que não pertence ao modelo do HUB.
// 2) Padroniza valores de forma conservadora (só altera quando há segurança).
//    Campo ausente continua null: nada é inventado.
// =====================================================================

const PARTICULAS = new Set(['da', 'de', 'do', 'das', 'dos', 'e']);
const limpar = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

// Só ajusta a caixa se o nome veio TODO em maiúsculas ou TODO em minúsculas.
// Capitalização mista (ex.: "McDonald") é preservada.
function normalizarNome(nome) {
  const n = limpar(nome);
  if (n !== n.toUpperCase() && n !== n.toLowerCase()) return n;
  return n.toLowerCase().split(' ')
    .map((p, i) => (i > 0 && PARTICULAS.has(p) ? p : p.charAt(0).toUpperCase() + p.slice(1))).join(' ');
}

// Telefone -> só dígitos, DDD + número, sem +55 (a validação anterior já garantiu o formato)
function normalizarTelefone(v) {
  let d = String(v).replace(/\D/g, '');
  if ((d.length === 12 || d.length === 13) && d.startsWith('55')) d = d.slice(2);
  return d;
}

// Data -> AAAA-MM-DD (a validação anterior já garantiu que é uma data real)
function normalizarData(v) {
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/);
  return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
}

const emBranco = (v) => (v === undefined || v === null || v === '' ? null : v);

return $input.all().map((item) => {
  const j = item.json; const d = j.dados || {};
  const antes = {};
  const depois = {
    nome: emBranco(d.nome && normalizarNome(d.nome)),
    telefone: emBranco(d.telefone && normalizarTelefone(d.telefone)),
    email: emBranco(d.email && limpar(d.email).toLowerCase()),
    documento: emBranco(d.documento && d.documento.replace(/\D/g, '')),
    data_pedido: emBranco(d.data_pedido && normalizarData(d.data_pedido)),
    tipo: emBranco(d.tipo && limpar(d.tipo)),
    observacao: emBranco(d.observacao && limpar(d.observacao)),
    nota_fiscal: emBranco(d.nota_fiscal && limpar(d.nota_fiscal)),
  };
  // Registro do que mudou (útil para a apresentação e para auditoria)
  const alteracoes = Object.keys(depois)
    .filter((c) => d[c] !== undefined && d[c] !== depois[c])
    .map((c) => ({ campo: c, de: d[c], para: depois[c] }));

  return { json: {
    chave_registro: j.chave_registro,
    canal_origem: j.canal,
    recebido_em: j.recebido_em,
    ambiente: j.teste ? 'teste' : 'producao',
    ...depois,
    status_validacao: j.status_validacao,
    campos_removidos: Object.keys(j.campos_nao_mapeados || {}),   // campos recebidos que não fazem parte do modelo do HUB
    alteracoes,
    cenario: j.cenario,
    crm_simulado: j.crm_simulado,
  } };
});

// =====================================================================
// ETAPA 9 | CLASSIFICAR POR REGRAS
// Classificação por PALAVRAS-CHAVE (não é IA). Procura termos no tipo + observação
// (sem acento, sem diferenciar maiúsculas) e escolhe a regra com mais termos encontrados.
// Empate: vale a ordem da lista. Sem nenhum termo: "Não identificada" -> setor "Triagem".
// =====================================================================

const REGRAS = [
  { categoria: 'Atraso na entrega',        setor: 'Logística',      termos: ['atras', 'onde esta', 'rastre', 'previsao de entrega', 'nao chegou', 'demora'] },
  { categoria: 'Avaria ou extravio',       setor: 'Operacional',    termos: ['avaria', 'danific', 'extravi', 'sinistro', 'ocorrencia', 'quebrad'] },
  { categoria: 'Coleta e agendamento',     setor: 'Operacional',    termos: ['coleta', 'agendar', 'agendamento', 'retirada'] },
  { categoria: 'Cotação de frete',         setor: 'Comercial',      termos: ['cotacao', 'orcamento', 'proposta', 'frete'] },
  { categoria: 'Cobrança e boletos',       setor: 'Financeiro',     termos: ['boleto', 'fatura', 'segunda via', 'pagamento', 'cobranca', 'vencimento'] },
  { categoria: 'Reclamação e suporte',     setor: 'Atendimento',    termos: ['reclam', 'insatisf', 'duvida', 'atendimento', 'suporte', 'ajuda'] },
  { categoria: 'Cadastro e documentos',    setor: 'Administrativo', termos: ['cadastro', 'contrato', 'documentacao', 'certidao', 'atualizar dados'] },
];

const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
// o termo precisa começar numa palavra ("atras" casa com "atrasada", mas "frete" não casa dentro de "refrete")
const contem = (txt, termo) => new RegExp('(^|[^a-z0-9])' + termo).test(txt);

return $input.all().map((item) => {
  const j = item.json;
  const txt = semAcento(`${j.tipo || ''} ${j.observacao || ''}`);

  let melhor = null;
  for (const regra of REGRAS) {
    const achados = regra.termos.filter((t) => contem(txt, t));
    if (achados.length && (!melhor || achados.length > melhor.achados.length)) melhor = { regra, achados };
  }
  return { json: {
    ...j,
    categoria: melhor ? melhor.regra.categoria : 'Não identificada',
    setor_responsavel: melhor ? melhor.regra.setor : 'Triagem',
    classificacao_metodo: 'regras_palavras_chave',
    regra_classificacao: melhor ? `termos: ${melhor.achados.join(', ')}` : 'nenhum termo encontrado',
  } };
});

// =====================================================================
// ETAPAS 11 e 12 | INTEGRAR CRM E UNIFICAR
// Junta a resposta do CRM (node anterior) com o registro classificado e monta o registro final do HUB.
//  - CRM respondeu com cadastro  -> crm_status "encontrado" (fonte crm_real)
//  - CRM respondeu sem cadastro  -> "nao_encontrado"
//  - CRM indisponível/não configurado -> "indisponivel"; se o item de TESTE trouxer dados
//    simulados, eles são usados e marcados "simulado_teste" (nunca passam por dados reais).
// Campos vazios do registro podem ser preenchidos pelo CRM; campos já preenchidos nunca são sobrescritos.
// =====================================================================

const registros = $('Classificar por Regras').all();   // registros antes do CRM (mesma ordem)
const respostas = $input.all();                        // respostas do HTTP Request

// Agrupa as respostas pelo registro de origem (uma consulta pode devolver 0, 1 ou vários itens)
const porRegistro = new Map();
respostas.forEach((r, i) => {
  const idx = r.pairedItem && r.pairedItem.item !== undefined ? r.pairedItem.item : i;
  if (!porRegistro.has(idx)) porRegistro.set(idx, []);
  porRegistro.get(idx).push(r.json || {});
});

const digitos = (s) => String(s ?? '').replace(/\D/g, '');

return registros.map((item, i) => {
  const j = item.json;
  const grupo = porRegistro.get(i) || [];
  const erro = grupo.find((g) => g.error);
  const ok = grupo.filter((g) => !g.error && Object.keys(g).length > 0);

  let crm = null; let status = 'indisponivel'; let fonte = null; let detalhe = null;

  if (ok.length) {                                       // resposta real do CRM
    const reg = ok[0].registro || ok[0];
    fonte = 'crm_real';
    if (reg.id !== undefined || reg.codigo !== undefined) { crm = reg; status = 'encontrado'; } else status = 'nao_encontrado';
  } else if (j.crm_simulado) {                           // SOMENTE testes: dados simulados
    fonte = 'simulado_teste';
    if (j.crm_simulado.encontrado) { crm = j.crm_simulado.registro; status = 'simulado_teste'; } else status = 'nao_encontrado';
  } else {
    detalhe = erro ? String(erro.error.message || erro.error) : 'CRM sem resposta';
  }

  // Preenche apenas o que está vazio
  const preenchidos = [];
  const final = { nome: j.nome, email: j.email, documento: j.documento };
  if (crm) {
    const nomeCrm = crm.nome || crm.razao_social;
    if (!final.nome && nomeCrm) { final.nome = nomeCrm; preenchidos.push('nome'); }
    if (!final.email && crm.email) { final.email = String(crm.email).toLowerCase(); preenchidos.push('email'); }
    if (!final.documento && (crm.documento || crm.cnpj)) { final.documento = digitos(crm.documento || crm.cnpj); preenchidos.push('documento'); }
  }

  // Registro unificado = colunas da tabela hub_registros
  return { json: {
    chave_registro: j.chave_registro,
    canal_origem: j.canal_origem,
    recebido_em: j.recebido_em,
    ambiente: j.ambiente,
    nome: final.nome,
    telefone: j.telefone,
    email: final.email,
    documento: final.documento,
    data_pedido: j.data_pedido,
    tipo: j.tipo,
    observacao: j.observacao,
    nota_fiscal: j.nota_fiscal,
    categoria: j.categoria,
    setor_responsavel: j.setor_responsavel,
    regra_classificacao: j.regra_classificacao,
    status_validacao: j.status_validacao,
    crm_status: status,
    crm_fonte: fonte,
    crm_id: crm && (crm.id ?? crm.codigo) !== undefined ? String(crm.id ?? crm.codigo) : null,
    crm_nome: crm ? (crm.nome || crm.razao_social || null) : null,
    crm_detalhe: detalhe,
    campos_preenchidos_pelo_crm: preenchidos,
    cenario: j.cenario,
  } };
});

// =====================================================================
// ETAPA 16 | NOTIFICAR SETOR
// Monta a notificação do setor que o Switch escolheu. O ENVIO REAL está pendente de configuração:
// não há destinatário nem canal definidos, então nada é enviado e nada é inventado.
// Para enviar de verdade, ligue a saída deste node a um node Email / Slack / WhatsApp
// e use os campos notificacao.assunto e notificacao.mensagem.
// =====================================================================
return $input.all().map((item) => {
  const j = item.json;
  const contato = [j.telefone, j.email].filter(Boolean).join(' / ') || 'não informado';
  const linhas = [
    `Categoria: ${j.categoria}`,
    `Cliente: ${j.nome || 'não informado'}`,
    `Contato: ${contato}`,
    `Solicitação: ${[j.tipo, j.observacao].filter(Boolean).join(' - ') || 'não informada'}`,
    `Canal: ${j.canal_origem}`,
    `Protocolo HUB: ${j.chave_registro}`,
  ];
  return { json: {
    chave_registro: j.chave_registro,
    setor_responsavel: j.setor_responsavel,
    notificacao: {
      assunto: `[HUB Rodomax] Nova solicitação para ${j.setor_responsavel}: ${j.categoria}`,
      mensagem: linhas.join('\n'),
      destinatario: null,
      status: 'pendente_configuracao',
    },
  } };
});

// =====================================================================================
// ETAPA 2 | IA 1 - GERAR BASE SINTÉTICA (e receber a demanda do formulário)
// Cria 300 demandas FICTÍCIAS de transporte, com rótulo "Atendida" / "Não atendida".
// ATENÇÃO: os rótulos vêm de HIPÓTESES OPERACIONAIS SIMULADAS (abaixo), não do histórico real
// da Rodomax. O modelo aprende os padrões dessas hipóteses, e não a realidade da empresa.
// A geração é determinística: a mesma SEMENTE produz sempre a mesma base (reprodutível).
// A demanda nova (preenchida no Formulário nativo do n8n) apenas atravessa este node:
// ela NÃO entra na base de treinamento.
// =====================================================================================

const SEMENTE = 20261125;      // semente fixa do gerador pseudoaleatório
const N_REGISTROS = 300;       // tamanho da base sintética
const CLASSES = ['Atendida', 'Não atendida'];

// Gerador pseudoaleatório determinístico (mulberry32): mesma semente => mesma sequência.
function criarGerador(semente) {
  let a = semente >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = criarGerador(SEMENTE);

// Sorteio ponderado: escolhe um valor de uma lista [[valor, peso], ...]
function sortear(opcoes) {
  const total = opcoes.reduce((s, o) => s + o[1], 0);
  let r = rnd() * total;
  for (const [valor, peso] of opcoes) { r -= peso; if (r <= 0) return valor; }
  return opcoes[opcoes.length - 1][0];
}
// Ruído com distribuição normal (Box-Muller)
function ruidoNormal(desvio) {
  const u1 = Math.max(rnd(), 1e-12), u2 = rnd();
  return desvio * Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
}
const sigmoide = (x) => 1 / (1 + Math.exp(-x));

// ---------------------------------------------------------------------------
// HIPÓTESES OPERACIONAIS (simuladas) usadas para definir o resultado.
// Cada fator soma (ou subtrai) "risco de não atendimento" a um escore. O escore, somado a um ruído
// aleatório, vira uma probabilidade; o rótulo é sorteado a partir dela. Assim NENHUM atributo
// isolado determina o resultado: há interações, limiares e acaso (erro irredutível).
// ---------------------------------------------------------------------------
const HIPOTESES = [
  'H1  Sem veículo disponível: risco muito maior (+2,0); sem motorista disponível: risco maior (+1,7); sem os dois, risco extra (+0,8).',
  'H2  Prazo curto aumenta o risco (1 dia +1,6; 2 dias +1,0; 3 dias +0,5; 4-5 dias +0,1); prazo de 10 dias ou mais reduz (-0,5).',
  'H3  Folga de prazo = prazo - distância/600 (hipótese: ~600 km percorridos por dia). Folga negativa: +1,8; folga entre 0 e 1 dia: +0,6.',
  'H4  Carga pesada exige veículo raro: acima de 20.000 kg +1,0; acima de 12.000 kg +0,4.',
  'H5  Tipo de carga: Perigosa +1,1 (motorista habilitado), Refrigerada +0,7 (veículo especial), Frágil +0,3, Granel +0,2, Geral 0.',
  'H6  Urgência alta com veículo e motorista disponíveis é priorizada (-0,6); urgência alta com algum recurso faltando agrava (+0,3).',
  'H7  Constante -2,2 (ajusta a proporção entre as classes) e ruído normal (desvio 0,8) para simular fatores não observados.',
];

function calcularEscore(d) {
  let s = -2.2;
  if (d.veiculo_disponivel === 'Não') s += 2.0;
  if (d.motorista_disponivel === 'Não') s += 1.7;
  if (d.veiculo_disponivel === 'Não' && d.motorista_disponivel === 'Não') s += 0.8;
  if (d.prazo_dias <= 1) s += 1.6;
  else if (d.prazo_dias === 2) s += 1.0;
  else if (d.prazo_dias === 3) s += 0.5;
  else if (d.prazo_dias <= 5) s += 0.1;
  else if (d.prazo_dias >= 10) s -= 0.5;
  const folga = d.prazo_dias - d.distancia_km / 600;
  if (folga < 0) s += 1.8; else if (folga < 1) s += 0.6;
  if (d.peso_kg > 20000) s += 1.0; else if (d.peso_kg > 12000) s += 0.4;
  s += { 'Perigosa': 1.1, 'Refrigerada': 0.7, 'Frágil': 0.3, 'Granel': 0.2, 'Geral': 0 }[d.tipo_carga];
  const semFalta = d.veiculo_disponivel === 'Sim' && d.motorista_disponivel === 'Sim';
  if (d.urgencia === 'alta') s += semFalta ? -0.6 : 0.3;
  return s;
}

const base = [];
const vistos = new Set();
let tentativas = 0;
while (base.length < N_REGISTROS && tentativas < 20000) {
  tentativas++;
  // --- atributos (distribuições plausíveis; urgência influencia o prazo) ---
  const urgencia = sortear([['baixa', 35], ['média', 40], ['alta', 25]]);
  const prazo_dias = urgencia === 'alta'
    ? sortear([[1, 30], [2, 30], [3, 20], [4, 10], [5, 10]])
    : urgencia === 'média'
      ? sortear([[2, 10], [3, 20], [4, 20], [5, 20], [7, 20], [10, 10]])
      : sortear([[4, 10], [5, 15], [7, 25], [10, 25], [15, 25]]);
  const faixa = rnd();
  const distancia_km = Math.round((faixa < 0.5 ? 50 + rnd() * 350 : faixa < 0.85 ? 400 + rnd() * 500 : 900 + rnd() * 1300) / 10) * 10;
  const peso_kg = Math.round(Math.exp(Math.log(300) + rnd() * (Math.log(32000) - Math.log(300))) / 50) * 50;
  const tipo_carga = sortear([['Geral', 40], ['Granel', 20], ['Refrigerada', 15], ['Frágil', 15], ['Perigosa', 10]]);
  const veiculo_disponivel = rnd() < 0.68 ? 'Sim' : 'Não';
  const motorista_disponivel = rnd() < 0.74 ? 'Sim' : 'Não';
  const d = { distancia_km, peso_kg, prazo_dias, tipo_carga, veiculo_disponivel, motorista_disponivel, urgencia };

  // evita registros idênticos
  const chave = JSON.stringify(d);
  if (vistos.has(chave)) continue;
  vistos.add(chave);

  // --- rótulo: escore + ruído -> probabilidade -> sorteio ---
  const p_nao_atendida = sigmoide(calcularEscore(d) + ruidoNormal(0.8));
  d.resultado = rnd() < p_nao_atendida ? 'Não atendida' : 'Atendida';
  base.push(d);
}
base.forEach((d, i) => { d.id = i + 1; });

// --- demanda nova (Formulário nativo do n8n): só passa adiante, NÃO treina ---
// O Form Trigger entrega cada resposta com o RÓTULO do campo como chave (ex.: "Distância (km)").
// Aqui os rótulos viram os nomes de atributo do modelo. Os nomes técnicos (distancia_km...) também
// são aceitos, para facilitar testes de código.
const CAMPOS_DO_FORMULARIO = {
  distancia_km:         ['Distância (km)', 'distancia_km'],
  peso_kg:              ['Peso da carga (kg)', 'peso_kg'],
  prazo_dias:           ['Prazo para atendimento (dias)', 'prazo_dias'],
  tipo_carga:           ['Tipo de carga', 'tipo_carga'],
  veiculo_disponivel:   ['Veículo disponível?', 'veiculo_disponivel'],
  motorista_disponivel: ['Motorista disponível?', 'motorista_disponivel'],
  urgencia:             ['Urgência', 'urgencia'],
};
const novas = $input.all().map((item, i) => {
  const j = item.json || {};
  const corpo = (j.body && typeof j.body === 'object') ? j.body : j;
  const bruta = {};
  for (const [atributo, nomes] of Object.entries(CAMPOS_DO_FORMULARIO)) {
    const achado = nomes.find((n) => corpo[n] !== undefined);
    bruta[atributo] = achado === undefined ? undefined : corpo[achado];
  }
  return { indice: i + 1, cenario: j._cenario || null, bruta };
});

const contagem = {};
CLASSES.forEach((c) => { contagem[c] = base.filter((d) => d.resultado === c).length; });

return [{ json: {
  base_sintetica: base,
  geracao: {
    semente: SEMENTE,
    registros: base.length,
    distribuicao_classes: contagem,
    percentual_nao_atendida: Math.round((100 * contagem['Não atendida']) / base.length * 10) / 10,
    aviso: 'Base 100% sintética. Os rótulos seguem hipóteses simuladas e não representam o histórico real da Rodomax.',
    hipoteses: HIPOTESES,
  },
  novas_demandas_brutas: novas,
} }];

// =====================================================================================
// ETAPA 2 | IA 2 - PREPARAR ATRIBUTOS E SEPARAR TREINO/TESTE
// 1) confere a base sintética e cria o atributo derivado km_por_dia;
// 2) separa treino (80%) e teste (20%) de forma ESTRATIFICADA (mantém a proporção das classes);
// 3) valida e padroniza a demanda nova vinda do formulário (aceita "sim/não", "media/média", maiúsculas etc.).
// As demandas novas NUNCA entram em treino nem em teste.
// =====================================================================================

const SEMENTE_SEPARACAO = 42;     // semente da divisão treino/teste (fixa => reprodutível)
const PROPORCAO_TESTE = 0.20;     // 80% treino / 20% teste

const d = $input.first().json;

// Atributos do modelo. tipo 'num' => divisões "atributo <= limiar"; 'cat' => divisões "atributo == valor".
const ATRIBUTOS = [
  { nome: 'distancia_km',         tipo: 'num', descricao: 'Distância entre origem e destino (km)' },
  { nome: 'peso_kg',              tipo: 'num', descricao: 'Peso da carga (kg)' },
  { nome: 'prazo_dias',           tipo: 'num', descricao: 'Prazo disponível para atendimento (dias)' },
  { nome: 'km_por_dia',           tipo: 'num', descricao: 'Derivado: distancia_km / prazo_dias (km exigidos por dia)' },
  { nome: 'tipo_carga',           tipo: 'cat', descricao: 'Geral, Granel, Refrigerada, Frágil ou Perigosa' },
  { nome: 'veiculo_disponivel',   tipo: 'cat', descricao: 'Sim ou Não' },
  { nome: 'motorista_disponivel', tipo: 'cat', descricao: 'Sim ou Não' },
  { nome: 'urgencia',             tipo: 'cat', descricao: 'baixa, média ou alta' },
];
const TIPOS_CARGA = ['Geral', 'Granel', 'Refrigerada', 'Frágil', 'Perigosa'];
const URGENCIAS = ['baixa', 'média', 'alta'];
const CLASSES = ['Atendida', 'Não atendida'];

// Gerador pseudoaleatório determinístico (mulberry32)
function criarGerador(semente) {
  let a = semente >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = criarGerador(SEMENTE_SEPARACAO);

const semAcento = (s) => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const comKm = (r) => ({ ...r, km_por_dia: Math.round((r.distancia_km / r.prazo_dias) * 10) / 10 });

// ---- 1) base: confere campos e cria o atributo derivado ----
const descartados = [];
const base = [];
for (const r of d.base_sintetica) {
  const ok = r.distancia_km > 0 && r.peso_kg > 0 && r.prazo_dias > 0 && TIPOS_CARGA.includes(r.tipo_carga)
    && ['Sim', 'Não'].includes(r.veiculo_disponivel) && ['Sim', 'Não'].includes(r.motorista_disponivel)
    && URGENCIAS.includes(r.urgencia) && CLASSES.includes(r.resultado);
  if (ok) base.push(comKm(r)); else descartados.push(r.id);
}

// ---- 2) separação estratificada: embaralha cada classe e reserva 20% dela para teste ----
function embaralhar(lista) { // Fisher-Yates com gerador determinístico
  const v = lista.slice();
  for (let i = v.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [v[i], v[j]] = [v[j], v[i]]; }
  return v;
}
const treino = [], teste = [];
for (const classe of CLASSES) {
  const grupo = embaralhar(base.filter((r) => r.resultado === classe));
  const nTeste = Math.round(grupo.length * PROPORCAO_TESTE);
  teste.push(...grupo.slice(0, nTeste));
  treino.push(...grupo.slice(nTeste));
}
const contar = (lista) => Object.fromEntries(CLASSES.map((c) => [c, lista.filter((r) => r.resultado === c).length]));

// faixas do treino (usadas para avisar quando uma demanda nova está fora do que o modelo viu)
const faixa = (campo) => ({ min: Math.min(...treino.map((r) => r[campo])), max: Math.max(...treino.map((r) => r[campo])) });
const faixas = { distancia_km: faixa('distancia_km'), peso_kg: faixa('peso_kg'), prazo_dias: faixa('prazo_dias') };

// ---- 3) validação e padronização das demandas novas ----
function lerSimNao(v) {
  const t = semAcento(v);
  if (['sim', 's', 'true', '1', 'yes'].includes(t)) return 'Sim';
  if (['nao', 'n', 'false', '0', 'no'].includes(t)) return 'Não';
  return null;
}
function lerNumero(v) {
  if (v === null || v === undefined || v === '') return NaN;
  if (typeof v === 'number') return v;
  const t = String(v).trim().replace(/\s/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
  return /^-?\d+(\.\d+)?$/.test(t) ? Number(t) : NaN;
}
const ROTULO = { distancia_km: 'Distância (km)', peso_kg: 'Peso da carga (kg)', prazo_dias: 'Prazo para atendimento (dias)',
  tipo_carga: 'Tipo de carga', veiculo_disponivel: 'Veículo disponível?', motorista_disponivel: 'Motorista disponível?', urgencia: 'Urgência' };
function validarDemanda(b) {
  const erros = [], avisos = [];
  const dist = lerNumero(b.distancia_km), peso = lerNumero(b.peso_kg), prazo = lerNumero(b.prazo_dias);
  if (!(dist >= 1 && dist <= 5000)) erros.push(`${ROTULO.distancia_km}: valor inválido (informe um número entre 1 e 5000): ${JSON.stringify(b.distancia_km ?? null)}`);
  if (!(peso >= 1 && peso <= 60000)) erros.push(`${ROTULO.peso_kg}: valor inválido (informe um número entre 1 e 60000): ${JSON.stringify(b.peso_kg ?? null)}`);
  if (!(Number.isInteger(prazo) && prazo >= 1 && prazo <= 90)) erros.push(`${ROTULO.prazo_dias}: valor inválido (informe um inteiro entre 1 e 90): ${JSON.stringify(b.prazo_dias ?? null)}`);
  const tipo = TIPOS_CARGA.find((t) => semAcento(t) === semAcento(b.tipo_carga ?? ''));
  if (!tipo) erros.push(`${ROTULO.tipo_carga}: valor inválido (use: ${TIPOS_CARGA.join(', ')}): ${JSON.stringify(b.tipo_carga ?? null)}`);
  const veic = lerSimNao(b.veiculo_disponivel ?? '');
  if (!veic) erros.push(`${ROTULO.veiculo_disponivel}: valor inválido (use Sim ou Não): ${JSON.stringify(b.veiculo_disponivel ?? null)}`);
  const mot = lerSimNao(b.motorista_disponivel ?? '');
  if (!mot) erros.push(`${ROTULO.motorista_disponivel}: valor inválido (use Sim ou Não): ${JSON.stringify(b.motorista_disponivel ?? null)}`);
  const urg = URGENCIAS.find((u) => semAcento(u) === semAcento(b.urgencia ?? ''));
  if (!urg) erros.push(`${ROTULO.urgencia}: valor inválido (use: ${URGENCIAS.join(', ')}): ${JSON.stringify(b.urgencia ?? null)}`);
  if (erros.length) return { valida: false, erros, avisos, demanda: null };

  const demanda = comKm({ distancia_km: dist, peso_kg: peso, prazo_dias: prazo, tipo_carga: tipo, veiculo_disponivel: veic, motorista_disponivel: mot, urgencia: urg });
  for (const campo of Object.keys(faixas)) {
    if (demanda[campo] < faixas[campo].min || demanda[campo] > faixas[campo].max) {
      avisos.push(`${ROTULO[campo]} = ${demanda[campo]} está fora da faixa vista no treino (${faixas[campo].min} a ${faixas[campo].max}): a previsão é uma extrapolação.`);
    }
  }
  return { valida: true, erros, avisos, demanda };
}
const novas = d.novas_demandas_brutas.map((n) => ({ indice: n.indice, cenario: n.cenario, bruta: n.bruta, ...validarDemanda(n.bruta || {}) }));

return [{ json: {
  atributos: ATRIBUTOS,
  classes: CLASSES,
  treino,
  teste,
  novas,
  geracao: d.geracao,
  preparacao: {
    registros_base: base.length,
    descartados_na_conferencia: descartados.length,
    semente_separacao: SEMENTE_SEPARACAO,
    proporcao_teste: PROPORCAO_TESTE,
    estratificada: true,
    treino: { registros: treino.length, classes: contar(treino) },
    teste: { registros: teste.length, classes: contar(teste) },
    atributo_derivado: 'km_por_dia = distancia_km / prazo_dias',
    faixas_treino: faixas,
  },
} }];

// =====================================================================================
// ETAPA 2 | IA 3 - TREINAR ÁRVORE DE DECISÃO (CART com índice Gini, JavaScript puro)
// Aprendizado supervisionado: a árvore aprende, SÓ com o conjunto de treino, quais perguntas
// (divisões) melhor separam "Atendida" de "Não atendida". Não há regras escritas à mão aqui:
// as perguntas e os limiares saem dos dados.
//
// Algoritmo (para cada nó, recursivamente):
//   1. calcula a impureza Gini do nó:  Gini = 1 - soma(proporção_da_classe^2)
//   2. testa todas as divisões possíveis de cada atributo:
//        numérico:    "atributo <= limiar" (limiar = ponto médio entre valores consecutivos)
//        categórico:  "atributo == valor"  (um valor contra os demais)
//   3. escolhe a divisão com maior GANHO = Gini(pai) - média ponderada dos Gini dos filhos
//   4. divide os registros e repete nos dois filhos
//   5. para (vira folha) quando: profundidade máxima, poucas amostras, nó puro,
//      nenhuma divisão com ganho positivo ou filhos menores que o mínimo por folha.
// =====================================================================================

// ---------------- PARÂMETROS (definidos antes de olhar o teste) ----------------
const PARAMETROS = {
  criterio: 'gini',
  profundidade_maxima: 5,        // limita o tamanho da árvore (controla overfitting)
  min_amostras_divisao: 10,      // nó com menos registros que isso não é dividido
  min_amostras_folha: 4,         // cada filho precisa ter pelo menos isso
  ganho_minimo: 1e-7,            // ganho de Gini mínimo para aceitar a divisão
};

const d = $input.first().json;
const CLASSES = d.classes;               // ['Atendida', 'Não atendida']
const ATRIBUTOS = d.atributos;
const treino = d.treino;                 // a árvore só enxerga este conjunto

// Conta quantos registros há de cada classe
function contarClasses(regs) {
  const c = Object.fromEntries(CLASSES.map((k) => [k, 0]));
  for (const r of regs) c[r.resultado]++;
  return c;
}
// Impureza de Gini a partir das contagens
function gini(contagem, n) {
  if (n === 0) return 0;
  let soma = 0;
  for (const k of CLASSES) soma += (contagem[k] / n) ** 2;
  return 1 - soma;
}
// Classe majoritária (empate: a primeira da lista)
function majoritaria(contagem) {
  return CLASSES.reduce((a, b) => (contagem[b] > contagem[a] ? b : a));
}

// Procura a melhor divisão do conjunto 'regs' entre todos os atributos e limiares.
function melhorDivisao(regs) {
  const n = regs.length;
  const contPai = contarClasses(regs);
  const giniPai = gini(contPai, n);
  let melhor = null;

  const avaliar = (atributo, op, valor, cEsq, nEsq) => {
    const nDir = n - nEsq;
    if (nEsq < PARAMETROS.min_amostras_folha || nDir < PARAMETROS.min_amostras_folha) return;
    const cDir = Object.fromEntries(CLASSES.map((k) => [k, contPai[k] - cEsq[k]]));
    const giniFilhos = (nEsq / n) * gini(cEsq, nEsq) + (nDir / n) * gini(cDir, nDir);
    const ganho = giniPai - giniFilhos;
    if (ganho > PARAMETROS.ganho_minimo && (!melhor || ganho > melhor.ganho + 1e-12)) {
      melhor = { atributo, op, valor, ganho };
    }
  };

  for (const attr of ATRIBUTOS) {
    if (attr.tipo === 'num') {
      // ordena pelo atributo e varre os pontos de corte, acumulando as contagens da esquerda
      const ord = regs.slice().sort((a, b) => a[attr.nome] - b[attr.nome]);
      const cEsq = Object.fromEntries(CLASSES.map((k) => [k, 0]));
      for (let i = 0; i < n - 1; i++) {
        cEsq[ord[i].resultado]++;
        const v1 = ord[i][attr.nome], v2 = ord[i + 1][attr.nome];
        if (v1 === v2) continue;                        // só corta entre valores diferentes
        avaliar(attr.nome, '<=', (v1 + v2) / 2, { ...cEsq }, i + 1);
      }
    } else {
      // categórico: testa "atributo == valor" para cada valor presente
      const valores = [...new Set(regs.map((r) => r[attr.nome]))];
      for (const v of valores) {
        const sub = regs.filter((r) => r[attr.nome] === v);
        avaliar(attr.nome, '==', v, contarClasses(sub), sub.length);
      }
    }
  }
  return melhor;
}

const testar = (r, dv) => (dv.op === '<=' ? r[dv.atributo] <= dv.valor : r[dv.atributo] === dv.valor);
const importancia = Object.fromEntries(ATRIBUTOS.map((a) => [a.nome, 0]));
const N_TOTAL = treino.length;

// Constrói a árvore recursivamente
function construir(regs, profundidade) {
  const n = regs.length;
  const contagem = contarClasses(regs);
  const g = gini(contagem, n);
  const folha = { tipo: 'folha', classe: majoritaria(contagem), n, contagem, gini: Math.round(g * 1000) / 1000 };

  // critérios de parada
  if (profundidade >= PARAMETROS.profundidade_maxima) return folha;
  if (n < PARAMETROS.min_amostras_divisao) return folha;
  if (g === 0) return folha;

  const dv = melhorDivisao(regs);
  if (!dv) return folha;

  importancia[dv.atributo] += (n / N_TOTAL) * dv.ganho;   // para a importância dos atributos
  const esq = regs.filter((r) => testar(r, dv));
  const dir = regs.filter((r) => !testar(r, dv));
  return {
    tipo: 'divisao',
    atributo: dv.atributo, op: dv.op, valor: dv.valor,
    n, contagem, gini: Math.round(g * 1000) / 1000, ganho: Math.round(dv.ganho * 1000) / 1000,
    esquerda: construir(esq, profundidade + 1),     // condição verdadeira
    direita: construir(dir, profundidade + 1),      // condição falsa
  };
}

// ---------------- TREINAMENTO ----------------
const arvore = construir(treino, 0);

// ---------------- Resumo e texto da árvore (para a apresentação) ----------------
let nNos = 0, nFolhas = 0, profReal = 0;
(function percorrer(no, p) { nNos++; profReal = Math.max(profReal, p);
  if (no.tipo === 'folha') { nFolhas++; return; }
  percorrer(no.esquerda, p + 1); percorrer(no.direita, p + 1); })(arvore, 0);

const fmtValor = (v) => (typeof v === 'number' ? String(Math.round(v * 100) / 100) : v);
const linhas = [];
(function imprimir(no, recuo) {
  if (no.tipo === 'folha') {
    linhas.push(`${recuo}=> ${no.classe}  (n=${no.n}; Atendida=${no.contagem['Atendida']}, Não atendida=${no.contagem['Não atendida']})`);
    return;
  }
  linhas.push(`${recuo}${no.atributo} ${no.op} ${fmtValor(no.valor)}  [n=${no.n}, gini=${no.gini}, ganho=${no.ganho}]`);
  imprimir(no.esquerda, recuo + '|  sim: ');
  imprimir(no.direita, recuo + '|  não: ');
})(arvore, '');

const somaImp = Object.values(importancia).reduce((a, b) => a + b, 0) || 1;
const importancias = Object.entries(importancia)
  .map(([atributo, v]) => ({ atributo, importancia: Math.round((v / somaImp) * 1000) / 1000 }))
  .sort((a, b) => b.importancia - a.importancia);

return [{ json: {
  ...d,
  modelo: {
    algoritmo: 'Árvore de Decisão (CART) com índice Gini, implementada em JavaScript puro',
    parametros: PARAMETROS,
    treinado_com: { registros: treino.length, classes: contarClasses(treino) },
    nos: nNos, folhas: nFolhas, profundidade_real: profReal,
    importancia_atributos: importancias,
    arvore_texto: linhas.join('\n'),
    arvore,
  },
} }];

// =====================================================================================
// ETAPA 2 | IA 4 - AVALIAR O MODELO, CLASSIFICAR A DEMANDA NOVA E MONTAR A TELA DE RESULTADO
// (junta os antigos "IA 4 - Avaliar" e "IA 5 - Classificar" para respeitar o limite de 25 nodes)
//
// PARTE A - AVALIAÇÃO: usa as 60 demandas de TESTE (que a árvore nunca viu). Todas as métricas
//   são calculadas a partir das previsões feitas aqui; nenhum número é digitado à mão.
//   Classe positiva = "Não atendida" (é o risco que a equipe quer detectar).
//     Precisão = dos casos que o modelo apontou como "Não atendida", quantos realmente eram.
//     Recall   = dos casos que realmente eram "Não atendida", quantos o modelo encontrou.
//     F1       = média harmônica de precisão e recall.
//   Linha de base: prever SEMPRE a classe mais frequente do conjunto de TREINO.
// PARTE B - CLASSIFICAÇÃO: usa a árvore treinada NESTA MESMA execução (nada fica em variável
//   global, arquivo ou banco). A demanda nova não participou do treino nem do teste.
//   Confiança estimada = (k+1)/(n+2) na folha (suavização de Laplace); NÃO é probabilidade calibrada.
// PARTE C - APRESENTAÇÃO: monta uma página HTML simples (campo "html") que o próximo node
//   (Form - Ending) mostra ao usuário. É APOIO À DECISÃO, não decisão definitiva.
// =====================================================================================

const d = $input.first().json;
const POSITIVA = 'Não atendida', NEGATIVA = 'Atendida';
const arvore = d.modelo.arvore;
const fmt = (v) => (typeof v === 'number' ? String(Math.round(v * 100) / 100) : v);

// Percorre a árvore até uma folha, registrando cada pergunta respondida (caminho de decisão)
function preverComCaminho(no, r) {
  const caminho = [];
  while (no.tipo === 'divisao') {
    const cond = no.op === '<=' ? r[no.atributo] <= no.valor : r[no.atributo] === no.valor;
    caminho.push({ pergunta: `${no.atributo} ${no.op} ${fmt(no.valor)}`, valor_da_demanda: r[no.atributo], resposta: cond ? 'sim' : 'não' });
    no = cond ? no.esquerda : no.direita;
  }
  return { folha: no, caminho };
}
const prever = (r) => preverComCaminho(arvore, r).folha.classe;

// ======================= PARTE A - AVALIAÇÃO NO CONJUNTO DE TESTE =======================
const cTreino = d.modelo.treinado_com.classes;
const classeBase = cTreino[POSITIVA] > cTreino[NEGATIVA] ? POSITIVA : NEGATIVA;   // linha de base

function metricas(reais, previstos) {
  let vp = 0, fp = 0, fn = 0, vn = 0;
  reais.forEach((real, i) => {
    const p = previstos[i];
    if (real === POSITIVA && p === POSITIVA) vp++;
    else if (real !== POSITIVA && p === POSITIVA) fp++;
    else if (real === POSITIVA && p !== POSITIVA) fn++;
    else vn++;
  });
  const div = (a, b) => (b === 0 ? 0 : a / b);        // convenção: divisão por zero => 0
  const precisao = div(vp, vp + fp), recall = div(vp, vp + fn);
  const arred = (x) => Math.round(x * 1000) / 1000;
  return {
    acuracia: arred(div(vp + vn, reais.length)), precisao: arred(precisao), recall: arred(recall),
    f1: arred(div(2 * precisao * recall, precisao + recall)),
    matriz_confusao: {
      legenda: 'linhas = classe real; colunas = classe prevista',
      rotulos: [NEGATIVA, POSITIVA], valores: [[vn, fp], [fn, vp]],
      vn_atendida_prevista_atendida: vn, fp_atendida_prevista_nao_atendida: fp,
      fn_nao_atendida_prevista_atendida: fn, vp_nao_atendida_prevista_nao_atendida: vp,
    },
  };
}
const reaisTeste = d.teste.map((r) => r.resultado);
const prevTeste = d.teste.map((r) => prever(r));
const arvoreTeste = metricas(reaisTeste, prevTeste);
const baseTeste = metricas(reaisTeste, d.teste.map(() => classeBase));
const acuraciaTreino = metricas(d.treino.map((r) => r.resultado), d.treino.map((r) => prever(r))).acuracia;

// Comparação honesta com a linha de base
const ganho = Math.round((arvoreTeste.acuracia - baseTeste.acuracia) * 1000) / 1000;
const veredito = ganho > 0
  ? `A árvore SUPEROU a linha de base: acurácia ${arvoreTeste.acuracia} contra ${baseTeste.acuracia} (+${ganho}). A linha de base (sempre "${classeBase}") tem recall ${baseTeste.recall}: não detecta nenhuma demanda em risco; a árvore detecta ${arvoreTeste.recall}.`
  : `A árvore NÃO superou a linha de base: acurácia ${arvoreTeste.acuracia} contra ${baseTeste.acuracia}. Possíveis causas: base pequena, ruído nos rótulos sintéticos ou árvore ajustada demais ao treino.`;
const comPrev = d.teste.map((r, i) => ({ ...r, previsto: prevTeste[i] }));
const erros = comPrev.filter((r) => r.previsto !== r.resultado);
const avaliacao = {
  conjunto: `teste (${d.teste.length} demandas nunca vistas no treino)`,
  classe_positiva: POSITIVA,
  arvore_de_decisao: arvoreTeste,
  linha_de_base: { regra: `prever sempre "${classeBase}" (classe mais frequente no treino)`, ...baseTeste },
  acuracia_no_treino: acuraciaTreino,
  diferenca_acuracia_treino_menos_teste: Math.round((acuraciaTreino - arvoreTeste.acuracia) * 1000) / 1000,
  ganho_de_acuracia_sobre_a_linha_de_base: ganho,
  superou_a_linha_de_base: ganho > 0,
  veredito,
  observacao: `Com apenas ${d.teste.length} demandas de teste, cada erro altera a acurácia em ~${Math.round(1000 / d.teste.length) / 10} ponto percentual: os números são indicativos.`,
  erros_no_teste: erros.length,
  exemplos_de_erros_falso_positivo: erros.filter((r) => r.previsto === POSITIVA).slice(0, 3),
  exemplos_de_erros_falso_negativo: erros.filter((r) => r.previsto !== POSITIVA).slice(0, 3),
  exemplos_de_acertos: comPrev.filter((r) => r.previsto === r.resultado).slice(0, 3),
};

// ======================= PARTE B - CLASSIFICAÇÃO DA DEMANDA NOVA =======================
const principais = d.modelo.importancia_atributos.filter((a) => a.importancia > 0).slice(0, 3);
const modelo = {
  algoritmo: d.modelo.algoritmo, parametros: d.modelo.parametros,
  treinado_com: `${d.modelo.treinado_com.registros} demandas sintéticas`,
  acuracia_no_teste: arvoreTeste.acuracia, f1_no_teste: arvoreTeste.f1,
  acuracia_linha_de_base: baseTeste.acuracia, superou_a_linha_de_base: avaliacao.superou_a_linha_de_base,
};
const AVISO = 'Ferramenta de apoio à decisão treinada com dados SINTÉTICOS (hipóteses simuladas); não representa o histórico real da Rodomax e não deve ser a única base para recusar ou aceitar uma demanda.';

// ======================= PARTE C - PÁGINA HTML DE RESULTADO =======================
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const ROTULO = { distancia_km: 'Distância (km)', peso_kg: 'Peso da carga (kg)', prazo_dias: 'Prazo (dias)', km_por_dia: 'Km exigidos por dia (distância ÷ prazo)',
  tipo_carga: 'Tipo de carga', veiculo_disponivel: 'Veículo disponível', motorista_disponivel: 'Motorista disponível', urgencia: 'Urgência' };
const EST = 'font-family:Arial,Helvetica,sans-serif;max-width:720px;margin:0 auto;text-align:left;line-height:1.45;font-size:15px';
const TH = 'border:1px solid #bbb;padding:4px 8px;background:#f1f1f1;text-align:center';
const TD = 'border:1px solid #bbb;padding:4px 8px;text-align:center';
const pct = (x) => `${Math.round(x * 1000) / 10}%`;
const a = arvoreTeste, b = baseTeste, mc = a.matriz_confusao;

const blocoModelo = `
<h3 style="margin:18px 0 6px">Quão confiável é o modelo? (teste com ${d.teste.length} demandas que ele nunca viu)</h3>
<table style="border-collapse:collapse;width:100%"><tr><th style="${TH}"></th><th style="${TH}">Acurácia</th><th style="${TH}">Precisão</th><th style="${TH}">Recall</th><th style="${TH}">F1</th></tr>
<tr><td style="${TD}"><b>Árvore de decisão</b></td><td style="${TD}">${a.acuracia}</td><td style="${TD}">${a.precisao}</td><td style="${TD}">${a.recall}</td><td style="${TD}">${a.f1}</td></tr>
<tr><td style="${TD}">Linha de base (sempre "${esc(classeBase)}")</td><td style="${TD}">${b.acuracia}</td><td style="${TD}">${b.precisao}</td><td style="${TD}">${b.recall}</td><td style="${TD}">${b.f1}</td></tr></table>
<p style="margin:8px 0 4px"><b>Matriz de confusão da árvore</b> (linhas = real; colunas = previsto): real Atendida → ${mc.vn_atendida_prevista_atendida} previstas Atendida e ${mc.fp_atendida_prevista_nao_atendida} previstas Não atendida; real Não atendida → ${mc.fn_nao_atendida_prevista_atendida} previstas Atendida e ${mc.vp_nao_atendida_prevista_nao_atendida} previstas Não atendida.</p>
<p style="margin:4px 0">${esc(veredito)} Acurácia no treino: ${acuraciaTreino} (diferença para o teste: ${avaliacao.diferenca_acuracia_treino_menos_teste}). ${esc(avaliacao.observacao)}</p>
<p style="margin:10px 0 0;padding:8px;background:#fff4e5;border:1px solid #f0c27b"><b>Atenção:</b> ${esc(AVISO)}</p>`;

function paginaDe(conteudo) {
  return `<div style="${EST}"><h2 style="margin:0 0 8px">Classificação de demanda — Rodomax Transportes</h2>${conteudo}${blocoModelo}</div>`;
}

// ---- uma saída por demanda recebida (pelo formulário, será uma) ----
return d.novas.map((n) => {
  const base = { demanda_numero: n.indice, cenario: n.cenario, entrada_recebida: n.bruta };
  if (!n.valida) {
    const html = paginaDe(`<div style="padding:10px;background:#fdecea;border:1px solid #e57373"><b>Não foi possível classificar: há problemas nos dados informados.</b>
      <ul style="margin:6px 0 0 18px">${n.erros.map((e) => `<li>${esc(e)}</li>`).join('')}</ul>Corrija os campos e envie o formulário novamente.</div>`);
    return { json: { ...base, status: 'entrada_invalida', erros: n.erros,
      mensagem: 'A demanda não foi classificada porque a entrada é inválida. Corrija os campos indicados e envie novamente.', avaliacao, modelo, html } };
  }
  const { folha, caminho } = preverComCaminho(arvore, n.demanda);
  const confianca = Math.round(((folha.contagem[folha.classe] + 1) / (folha.n + 2)) * 1000) / 10;
  const pNao = Math.round(((folha.contagem[POSITIVA] + 1) / (folha.n + 2)) * 1000) / 10;
  const naoAtendida = folha.classe === POSITIVA;
  const condicoes = caminho.map((c) => `${c.pergunta} (${c.resposta})`).join('; ') || 'nenhuma divisão (árvore de um só nó)';
  const interpretacao = naoAtendida
    ? `Características semelhantes às de demandas classificadas como NÃO ATENDIDAS no conjunto de treinamento: ${folha.contagem[POSITIVA]} de ${folha.n} demandas de treino que chegaram a esta mesma folha não foram atendidas. Sugestão: priorizar a verificação de veículo, motorista e prazo desta demanda.`
    : `Características semelhantes às de demandas ATENDIDAS no conjunto de treinamento: ${folha.contagem['Atendida']} de ${folha.n} demandas de treino que chegaram a esta mesma folha foram atendidas. Isso indica condições favoráveis, não garantia de atendimento.`;
  const atributosDaDecisao = [...new Set(caminho.map((c) => c.pergunta.split(' ')[0]))];

  const cor = naoAtendida ? '#c62828' : '#2e7d32', fundo = naoAtendida ? '#fdecea' : '#e8f5e9';
  const entrada = Object.entries(n.demanda).map(([k, v]) => `<li>${esc(ROTULO[k] || k)}: <b>${esc(v)}</b></li>`).join('');
  const passos = caminho.map((c) => `<li>${esc(ROTULO[c.pergunta.split(' ')[0]] || c.pergunta.split(' ')[0])}: <code>${esc(c.pergunta)}</code> — valor desta demanda: <b>${esc(fmt(c.valor_da_demanda))}</b> → <b>${c.resposta}</b></li>`).join('');
  const html = paginaDe(`
    <div style="padding:12px;background:${fundo};border:2px solid ${cor};text-align:center">
      <div style="font-size:13px;color:#555">Classe prevista</div>
      <div style="font-size:28px;font-weight:bold;color:${cor}">${esc(folha.classe)}</div>
      <div>Confiança estimada: <b>${confianca}%</b> <span style="font-size:12px;color:#555">(frequência na folha da árvore, não é probabilidade calibrada)</span></div></div>
    <h3 style="margin:16px 0 4px">O que isso significa</h3><p style="margin:0">${esc(interpretacao)}</p>
    <h3 style="margin:16px 0 4px">Caminho de decisão da árvore</h3><ol style="margin:0 0 0 20px">${passos || '<li>Árvore sem divisões.</li>'}</ol>
    <p style="margin:6px 0 0">Base da confiança: folha com ${folha.n} demandas de treino (Atendida=${folha.contagem['Atendida']}, Não atendida=${folha.contagem['Não atendida']}).</p>
    <h3 style="margin:16px 0 4px">Principais atributos considerados</h3>
    <p style="margin:0">Nesta decisão: ${atributosDaDecisao.map((x) => esc(ROTULO[x] || x)).join(', ')}.<br>
    Mais importantes no modelo (redução de Gini): ${principais.map((p) => `${esc(ROTULO[p.atributo] || p.atributo)} (${p.importancia})`).join(', ')}.</p>
    ${n.avisos.length ? `<div style="margin-top:12px;padding:8px;background:#fff4e5;border:1px solid #f0c27b"><b>Avisos:</b><ul style="margin:4px 0 0 18px">${n.avisos.map((x) => `<li>${esc(x)}</li>`).join('')}</ul></div>` : ''}
    <h3 style="margin:16px 0 4px">Demanda informada</h3><ul style="margin:0 0 0 20px">${entrada}</ul>`);

  return { json: {
    ...base, status: 'classificada', classe_prevista: folha.classe,
    confianca_estimada_percentual: confianca, probabilidade_estimada_nao_atendida_percentual: pNao,
    base_da_confianca: `folha com ${folha.n} demandas de treino (Atendida=${folha.contagem['Atendida']}, Não atendida=${folha.contagem['Não atendida']}); suavização de Laplace`,
    interpretacao, atributos_da_decisao: atributosDaDecisao, caminho_de_decisao: caminho, resumo_do_caminho: condicoes,
    atributos_mais_importantes_no_modelo: principais, demanda_padronizada: n.demanda, avisos: n.avisos,
    avaliacao, modelo, aviso_de_uso: AVISO, html,
  } };
});

